SELECT id, electricity_category AS electricityCategory, base_price AS basePrice, peak_price AS peakPrice, valley_price AS valleyPrice, effective_date AS effectiveDate, implementation_plan AS implementationPlan, preferential_policy AS preferentialPolicy, pricing_method AS pricingMethod, create_time AS createTime FROM price_standard
deleted = 0
AND electricity_category = #{electricityCategory}
AND pricing_method = #{pricingMethod}
AND effective_date <= #{effectiveDate}
ORDER BY effective_date ASC

